draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.lineWidth = 1.5;

var pad = W * 0.06;
var panelW = (W - 3 * pad) / 2;
var top = H * 0.22, bot = H * 0.68;

// ---- left panel: stacked layers (series) ----
var ax = pad;
ctx.fillStyle = C.ink;
ctx.fillText("Stacked layers: same Q, voltages add", ax, H * 0.13);
ctx.fillStyle = C.figure;
ctx.fillRect(ax, top - 8, panelW, 8);
ctx.fillRect(ax, bot, panelW, 8);
var mid = top + (bot - top) * 0.45;
ctx.globalAlpha = 0.35; ctx.fillStyle = C.faint;
ctx.fillRect(ax, top, panelW, mid - top);
ctx.globalAlpha = 0.18;
ctx.fillRect(ax, mid, panelW, bot - mid);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule;
ctx.strokeRect(ax, top, panelW, mid - top);
ctx.strokeRect(ax, mid, panelW, bot - mid);
ctx.fillStyle = C.ink;
ctx.fillText("k1, thickness d1", ax + 6, (top + mid) / 2 + 4);
ctx.fillText("k2, thickness d2", ax + 6, (mid + bot) / 2 + 4);
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(ax + panelW + 10, top); ctx.lineTo(ax + panelW + 10, bot); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("V = V1 + V2", ax + panelW - 4, bot + 22);
ctx.fillStyle = C.ink;
ctx.fillText("1/C = d1/(k1 e0 A) + d2/(k2 e0 A)", ax, bot + 40);

// ---- right panel: side by side (parallel) ----
var bx = 2 * pad + panelW;
ctx.fillStyle = C.ink;
ctx.fillText("Side by side: same V, charges add", bx, H * 0.13);
ctx.fillStyle = C.figure;
ctx.fillRect(bx, top - 8, panelW, 8);
ctx.fillRect(bx, bot, panelW, 8);
var split = bx + panelW * 0.5;
ctx.globalAlpha = 0.35; ctx.fillStyle = C.faint;
ctx.fillRect(bx, top, panelW * 0.5, bot - top);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.rule;
ctx.strokeRect(bx, top, panelW * 0.5, bot - top);
ctx.strokeRect(split, top, panelW * 0.5, bot - top);
ctx.fillStyle = C.ink;
ctx.fillText("k, area A1", bx + 4, (top + bot) / 2 + 4);
ctx.fillText("air, A2", split + 4, (top + bot) / 2 + 4);
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(bx + 12, top); ctx.lineTo(bx + 12, bot); ctx.stroke();
ctx.beginPath(); ctx.moveTo(split + 12, top); ctx.lineTo(split + 12, bot); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("same V across both", bx, bot + 22);
ctx.fillStyle = C.ink;
ctx.fillText("C = k e0 A1/d + e0 A2/d", bx, bot + 40);

out.note = "Cut along the field lines and the pieces are in parallel; cut across them and the pieces are in series.";
